const TZ = 'America/New_York';
const agora = $now.setZone(TZ);

function proximaJanelaValida(dt) {
  let t = dt;
  for (let i = 0; i < 14; i++) {
    if (t.weekday === 7) { t = t.plus({ days: 1 }).set({ hour: 7, minute: 0, second: 0, millisecond: 0 }); continue; }
    if (t.hour < 7)      { t = t.set({ hour: 7, minute: 0, second: 0, millisecond: 0 }); continue; }
    if (t.hour >= 20)    { t = t.plus({ days: 1 }).set({ hour: 7, minute: 0, second: 0, millisecond: 0 }); continue; }
    return t;
  }
  return t;
}

function dentroJanelaComercial(dt) {
  return dt.weekday !== 7 && dt.hour >= 7 && dt.hour < 20;
}

const saida = [];

for (const item of $input.all()) {
  const row = item.json || {};
  if (!row.id || !row.identificador) continue; // item vazio do Always Output Data

  const etapa = Number(row.etapa || 1);
  const canal = String(row.canal || 'instagram');
  const ultimaCliente = DateTime.fromISO(String(row.ultima_msg_cliente_em || ''), { zone: TZ });
  if (!ultimaCliente.isValid) continue;

  // Limite absoluto da janela da Meta (23h30 após a última msg do lead).
  // Só vale para Instagram/Messenger — WhatsApp não tem essa janela.
  const limiteMeta = ultimaCliente.plus({ hours: 23, minutes: 30 });

  const base = {
    ...row,
    status: row.status || 'agendado',
    etapa,
    canal,
    _agora: agora.toISO(),
    _limite_meta: limiteMeta.toISO()
  };

  // ---------- DIA COMBINADO + INSTAGRAM + janela da Meta fechada ----------
  // O cliente pediu contato neste dia, mas a Carol não pode mais
  // enviar pela API da Meta → fica pendente no CRM para
  // retomar manualmente. (O aviso vai para o Samuel, não para o
  // lead, por isso não depende da janela comercial.)
  const diaCombinado = String(row.dia_combinado || '').trim();
  if (etapa>=3 || etapa<1 || !Number.isInteger(etapa) || Number(row.tentativas_enviadas || 0)>=2) { saida.push({json:{...base,acao:'reagendar',status:'encerrado',motivo_trava:'ciclo completo (max 2 tentativas)'}}); continue; }
  if (diaCombinado && canal !== 'whatsapp' && agora > limiteMeta) {
    saida.push({ json: { ...base, acao: 'notificar_samuel' } });
    continue;
  }

  // ---------- ETAPA 3+ → encerra ----------
  // Também apanha linhas antigas que ficaram paradas em etapa 3/4.
  if (etapa >= 3 || etapa < 1 || Number.isNaN(etapa)) {
    saida.push({ json: { ...base, acao: 'reagendar', status: 'encerrado',
      proxima_tentativa_em: row.proxima_tentativa_em,
      motivo_trava: 'ciclo completo (max 2 tentativas)' } });
    continue;
  }

  // ============================================================
  // WHATSAPP — etapas 1 e 2; sem janela da Meta.
  // ============================================================
  if (canal === 'whatsapp') {

    // Fora do horário comercial? Adia para a próxima janela.
    if (!dentroJanelaComercial(agora)) {
      saida.push({ json: { ...base, acao: 'reagendar',
        proxima_tentativa_em: proximaJanelaValida(agora).toISO(),
        motivo_trava: 'fora do horario comercial' } });
      continue;
    }

    // Pode enviar ao lead.
    saida.push({ json: { ...base, acao: 'enviar_lead' } });
    continue;
  }

  // ============================================================
  // INSTAGRAM / MESSENGER — etapas 1 e 2; com janela da Meta.
  // ============================================================

  // Janela da Meta já fechou? O lead não pode mais receber pela
  // API — sem dia combinado, o ciclo encerra (o caso COM dia
  // combinado já foi tratado acima, com aviso ao Samuel).
  if (agora > limiteMeta) {
    saida.push({ json: { ...base, acao: 'reagendar', status: 'encerrado',
      proxima_tentativa_em: row.proxima_tentativa_em,
      motivo_trava: 'janela da Meta fechou antes da etapa ' + etapa } });
    continue;
  }

  // Fora do horário comercial agora? Tenta adiar para a próxima
  // janela — mas só se ela ainda couber dentro da janela da Meta.
  if (!dentroJanelaComercial(agora)) {
    const proxima = proximaJanelaValida(agora);
    if (proxima <= limiteMeta) {
      saida.push({ json: { ...base, acao: 'reagendar',
        proxima_tentativa_em: proxima.toISO(),
        motivo_trava: 'fora do horario comercial' } });
    } else {
      saida.push({ json: { ...base, acao: 'reagendar', status: 'encerrado',
        proxima_tentativa_em: row.proxima_tentativa_em,
        motivo_trava: 'sem horario comercial dentro da janela da Meta' } });
    }
    continue;
  }

  // Tudo certo: pode enviar ao lead.
  saida.push({ json: { ...base, acao: 'enviar_lead' } });
}

return saida;

