const lead = $('Montar Análise do Juiz').item.json;


const bruto = String($json.text || $json.output || '').trim();

let decisao = '';
let motivo = '';
let angulo = '';
let situacaoPlaybook = '';

try {
  // Tira cercas de markdown se vierem (```json ... ```).
  const limpo = bruto.replace(/^```json?\s*/i, '').replace(/```\s*$/i, '').trim();
  const obj = JSON.parse(limpo);
  if (Object.keys(obj).some(k=>!['decisao','motivo','angulo','situacao_playbook'].includes(k)) || ['decisao','motivo','angulo','situacao_playbook'].some(k=>typeof obj[k]!=='string')) throw new Error('judge_structure_invalid');
  decisao = String(obj.decisao || '').toLowerCase().trim();
  motivo  = String(obj.motivo || '').trim();
  angulo  = String(obj.angulo || '').trim();
  situacaoPlaybook = String(obj.situacao_playbook || '').toLowerCase().trim();
} catch (e) {
  decisao = '';
}

// Decisão inválida → perfil ativo: follow-up leve na dúvida.
if (!['enviar', 'pular', 'encerrar'].includes(decisao)) {
  throw new Error('judge_result_invalid');
}

// TRAVA DETERMINÍSTICA (caso Nathan): com ZERO follow-ups enviados, "pular"
// é PROIBIDO — a única razão válida de pular é não empilhar follow-up em cima
// de outro follow-up, e sem tentativas não existe follow-up nenhum. O Juiz já
// pulou um lead parado no recapitulativo final ("vale aguardar") e o lead
// esfriou. Se ele pular com tentativas = 0, vira "enviar" na marra.
// EXCEÇÃO: o caso "EU TE AVISO" na etapa 1 — o Juiz menciona isso no motivo,
// e nesse caso o pular é legítimo mesmo com 0 tentativas.
const tentativasJaEnviadas = Number(lead.tentativas_enviadas || 0);
const pularLegitimoTeAviso = /te aviso|let you know|eu te aviso|avisa|reach out/i.test(motivo);
if (decisao === 'pular' && tentativasJaEnviadas === 0 && !pularLegitimoTeAviso) {
  decisao = 'enviar';
  motivo = 'guardrail: juiz pulou com 0 tentativas enviadas (motivo original: ' + motivo + ')';
  if (!angulo) angulo = 'retomar a conversa do ponto exato em que parou, de forma leve';
}

// TRAVA DO DIA COMBINADO: o cliente pediu contato neste dia.
// "pular" aqui quebraria a promessa — vira "enviar" na marra.
const temDiaCombinado = String(lead.dia_combinado || '').trim() !== '';
if (temDiaCombinado && decisao === 'pular') {
  decisao = 'enviar';
  motivo = 'guardrail: dia combinado pelo cliente — contato obrigatorio (motivo original: ' + motivo + ')';
}
if (temDiaCombinado && decisao === 'enviar' && !angulo) {
  angulo = 'retomar lembrando com leveza que o cliente pediu contato hoje e avancar do ponto onde a conversa parou';
}

// Enviar sem ângulo → dá um ângulo genérico leve.
if (decisao === 'enviar' && !angulo) {
  angulo = 'perguntar de forma leve se ficou alguma duvida sobre o tratamento';
}

// ---------- PLAYBOOK: valida a situação e monta o bloco do Redator ----------
const playbookRows = Array.isArray(lead.playbook_rows) ? lead.playbook_rows : [];
const linhaPlaybook = situacaoPlaybook
  ? (playbookRows.find(r => String(r.situacao || '').toLowerCase().trim() === situacaoPlaybook) || null)
  : null;

let blocoPlaybookRedator = '';
if (decisao === 'enviar' && linhaPlaybook) {
  blocoPlaybookRedator =
    'ESTRATEGIA DO PLAYBOOK — ' + String(linhaPlaybook.nome || linhaPlaybook.situacao) + ':\n' +
    'O que fazer (siga a risca, incluindo o que NAO fazer): ' + String(linhaPlaybook.abordagem || '') +
    (linhaPlaybook.exemplo_mensagem
      ? '\nReferencia de TOM (PROIBIDO copiar literalmente — escreva com suas palavras, no idioma do lead): "' + String(linhaPlaybook.exemplo_mensagem) + '"'
      : '');
}

return [{ pairedItem:{item:0}, json: {
  ...lead,
  decisao,
  motivo_juiz: motivo,
  angulo,
  situacao_playbook: linhaPlaybook ? String(linhaPlaybook.situacao) : '',
  bloco_playbook_redator: blocoPlaybookRedator
} }];

